struct Rect { int left, top, right, bottom; };
extern int far L, far T;
extern void far g(struct Rect far *r);

variants.member_reuse:
void far f(int x, int y, int h)
{
    struct Rect r;
    r.left = (x + 6) * 28 + L - y * 10;
    r.bottom = y * 10 + T + 0x47;
    r.top = r.bottom - h;
    r.right = r.left + 9;
    g(&r);
}

variants.local_copy:
void far f(int x, int y, int h)
{
    struct Rect r;
    int a;
    a = (x + 6) * 28 + L - y * 10;
    r.left = a;
    r.bottom = y * 10 + T + 0x47;
    r.top = r.bottom - h;
    r.right = a + 9;
    g(&r);
}
